#!/usr/bin/env python3
"""Regenerate the benchmark README index from case READMEs and public entries."""

import argparse
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT / "rust/tools"))
from public_conformance import plan


def render_index(fixtures, current):
    if len(re.findall(r"^## Benchmarks\n", current, re.MULTILINE)) != 1:
        raise ValueError("benchmark index requires exactly one '## Benchmarks' heading")
    prefix = current.split("## Benchmarks\n", 1)[0]
    payload = plan(fixtures)
    active = sum(not row["excluded"] for row in payload["examples"])
    lines = [
        "## Benchmarks",
        "",
        "<!-- Generated by .github/scripts/benchmark-docs/build_index.py. -->",
        "",
        f"{len(payload['examples'])} authored cases; {active} active cases use the same public",
        "Python and R plan. Host entries describe runnable metadata. Actual passing",
        "coverage is recorded separately in the [conformance observations](../rust/qualification/public-conformance.json).",
        "",
        "| Benchmark | Derives | Lifecycle | Public conformance |",
        "|---|---|---|---|",
    ]
    for row in payload["examples"]:
        name = row["name"]
        readme = (fixtures / name / "README.md").read_text(encoding="utf-8")
        title = re.search(r"^# (.+)$", readme, re.MULTILINE)
        lifecycle = re.search(
            r"\[!\[Lifecycle: [^\]\n]+\]\([^\)\n]+\)\]\([^\)\n]+\)", readme
        )
        if title is None or lifecycle is None:
            raise ValueError(f"missing title/lifecycle: {name}")
        description = title.group(1).replace("|", "\\|")
        coverage = f"Excluded: {row['excluded']}" if row["excluded"] else "Python, R"
        lines.append(
            f"| [`{name}`]({name}/) | {description} | {lifecycle.group()} | {coverage} |"
        )
    return prefix + "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--root", type=Path, default=ROOT)
    args = parser.parse_args()
    path = args.root / "benchmarks/README.md"
    try:
        current = path.read_text(encoding="utf-8")
        result = render_index(path.parent, current)
    except (OSError, ValueError) as error:
        print(f"Cannot generate benchmark index: {error}", file=sys.stderr)
        return 1
    if args.check:
        if result != current:
            print(f"Stale benchmark index: {path}", file=sys.stderr)
            return 1
    else:
        path.write_text(result, encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
